/* ── Table: hairline rows on the open grid; no cell borders ──
   Scoped to .rs-table so linking raster.css never restyles a table
   it doesn't own. The compat layer re-emits these on bare elements. */
.rs-table{width:calc(100% + 40px);border-collapse:collapse;margin:16px 0 24px -20px;font-size:14px}
.rs-table th{text-align:left;font-weight:600;color:var(--text);letter-spacing:-.01em;padding:10px 16px 10px 12px;border-bottom:2px solid var(--divider);font-size:13px}
.rs-table th:first-child{padding-left:20px}
.rs-table th:last-child{padding-right:20px}
.rs-table td{padding:10px 16px 10px 12px;color:var(--text-secondary);font-weight:500;letter-spacing:-.01em;border-bottom:1px solid var(--divider);vertical-align:top}
.rs-table td:first-child{padding-left:20px}
.rs-table td:last-child{padding-right:20px}
.rs-table tr:nth-child(even) td{background:var(--table-alt)}
.rs-table td:last-child,.rs-table th:last-child{text-align:right}
.rs-table tr.rs-total-row td{font-weight:500;color:var(--text);border-top:2px solid var(--divider);border-bottom:2px solid var(--divider)}
@media(max-width:640px){
  .rs-table{font-size:12px;width:calc(100% + 2*var(--pad));margin-left:calc(-1*var(--pad));margin-right:calc(-1*var(--pad))}
  .rs-table th{padding:8px 10px;font-size:12px}
  .rs-table td{padding:8px 10px}
  .rs-table th:first-child,.rs-table td:first-child{padding-left:var(--pad)}
  .rs-table th:last-child,.rs-table td:last-child{padding-right:var(--pad)}
}
